create extension if not exists pgcrypto;
create table coworkers (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, role text not null default 'General coworker', instructions text not null default '', status text not null default 'ready', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table tasks (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, coworker_id uuid not null references coworkers(id) on delete cascade, goal text not null, status text not null default 'queued', created_at timestamptz not null default now());
create table runs (id uuid primary key default gen_random_uuid(), task_id uuid not null references tasks(id) on delete cascade, status text not null default 'queued', started_at timestamptz, finished_at timestamptz, created_at timestamptz not null default now());
create table run_steps (id uuid primary key default gen_random_uuid(), run_id uuid not null references runs(id) on delete cascade, position integer not null, kind text not null, title text not null, status text not null default 'queued', input jsonb not null default '{}'::jsonb, output jsonb, created_at timestamptz not null default now(), unique(run_id,position));
create table memories (id uuid primary key default gen_random_uuid(), coworker_id uuid not null references coworkers(id) on delete cascade, kind text not null default 'working', content text not null, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table approvals (id uuid primary key default gen_random_uuid(), run_id uuid not null references runs(id) on delete cascade, action text not null, reason text not null, payload jsonb not null default '{}'::jsonb, status text not null default 'pending', decided_at timestamptz, created_at timestamptz not null default now());
create table activity_logs (id bigint generated always as identity primary key, run_id uuid references runs(id) on delete cascade, event_type text not null, message text not null, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
alter table coworkers enable row level security; alter table tasks enable row level security;
create policy coworkers_owner on coworkers for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy tasks_owner on tasks for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
alter table runs enable row level security;
alter table run_steps enable row level security;
alter table memories enable row level security;
alter table approvals enable row level security;
alter table activity_logs enable row level security;
create policy runs_owner on runs for all using (exists(select 1 from tasks t where t.id=runs.task_id and t.user_id=auth.uid())) with check (exists(select 1 from tasks t where t.id=runs.task_id and t.user_id=auth.uid()));
create policy run_steps_owner on run_steps for all using (exists(select 1 from runs r join tasks t on t.id=r.task_id where r.id=run_steps.run_id and t.user_id=auth.uid())) with check (exists(select 1 from runs r join tasks t on t.id=r.task_id where r.id=run_steps.run_id and t.user_id=auth.uid()));
create policy memories_owner on memories for all using (exists(select 1 from coworkers c where c.id=memories.coworker_id and c.user_id=auth.uid())) with check (exists(select 1 from coworkers c where c.id=memories.coworker_id and c.user_id=auth.uid()));
create policy approvals_owner on approvals for all using (exists(select 1 from runs r join tasks t on t.id=r.task_id where r.id=approvals.run_id and t.user_id=auth.uid())) with check (exists(select 1 from runs r join tasks t on t.id=r.task_id where r.id=approvals.run_id and t.user_id=auth.uid()));
create policy activity_logs_owner on activity_logs for all using (exists(select 1 from runs r join tasks t on t.id=r.task_id where r.id=activity_logs.run_id and t.user_id=auth.uid())) with check (exists(select 1 from runs r join tasks t on t.id=r.task_id where r.id=activity_logs.run_id and t.user_id=auth.uid()));